function App() {
  const REVALIDATE_MS = 3000;
  const [cached, setCached] = useState('Value v1');
  const [version, setVersion] = useState(1);
  const [lastBuilt, setLastBuilt] = useState(() => Date.now());
  const [log, setLog] = useState([]);
  const request = () => {
    const served = cached; // serve stale immediately
    const isStale = Date.now() - lastBuilt > REVALIDATE_MS;
    setLog((l) => [`Served "${served}"${isStale ? ' (stale -> rebuilding in background)' : ''}`, ...l].slice(0, 5));
    if (isStale) {
      setTimeout(() => {
        const next = version + 1;
        setVersion(next);
        setCached(`Value v${next}`);
        setLastBuilt(Date.now());
      }, 500); // background regeneration
    }
  };
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <h3>ISR (revalidate {REVALIDATE_MS / 1000}s)</h3>
      <button onClick={request}>Simulate a request</button>
      <p>Cached now: <b>{cached}</b></p>
      <ul style={{ fontSize: 12 }}>{log.map((m, i) => <li key={i}>{m}</li>)}</ul>
      <p style={{ fontSize: 12, color: '#666' }}>After the window, a request serves stale and rebuilds in the background.</p>
    </div>
  );
}

