// app/products/[id]/page.tsx — ISR with a tag + window
export async function generateStaticParams() {
  const ids = await fetch('https://api.example.com/product-ids').then((r) => r.json());
  return ids.map((id: string) => ({ id }));
}

export default async function ProductPage({ params }: { params: { id: string } }) {
  const product = await fetch(`https://api.example.com/products/${params.id}`, {
    next: { revalidate: 3600, tags: [`product:${params.id}`] }, // hourly window + tag
  }).then((r) => r.json());

  return (
    <main>
      <h1>{product.name}</h1>
      <p>${product.price}</p>
    </main>
  );
}

// app/api/revalidate/route.ts — called by the price-update webhook
import { revalidateTag } from 'next/cache';

export async function POST(req: Request) {
  const { id } = await req.json();
  revalidateTag(`product:${id}`); // refresh just this product immediately
  return Response.json({ revalidated: true });
}
